// program_mem_tb: runs tb/core/program.mem (generated by mkprog.py), loaded by
// kc_soc's imem through $readmemh, and checks that it prints
// "Hello, world!\r\n" over UART_TX at 1 Mbaud, never writes UART_TX while TX
// is busy, and loops back from the final jal to 0x0000_0004. The testbench
// never writes the instruction memory through hierarchy.
module program_mem_tb;
    parameter string IMEM_HEX = "";
    parameter string DMEM_HEX = "";
    `include "soc_harness.svh"

    localparam string MESSAGE    = "Hello, world!\r\n";
    localparam int    BYTE_COUNT = 15;
    localparam logic [31:0] LOOP_JAL = 32'h0000_0130;

    int   start_count   = 0;
    logic saw_loop_jump = 1'b0;
    logic [31:0] previous_pc = '0;

    always @(posedge clk) begin
        if (!rst) begin
            if (err_led !== 1'b0) $fatal(1, "FAIL: error LED on, ERR_PC=%08h", dut.u_mmio.err_pc);
            if (dut.u_mmio.uart_tx_start) begin
                if (dut.u_uart.tx_busy !== 1'b0)
                    $fatal(1, "FAIL: UART_TX written while TX busy");
                start_count <= start_count + 1;
            end
            if (previous_pc == LOOP_JAL && `KC_CORE.pc == 32'h0000_0004) saw_loop_jump <= 1'b1;
            previous_pc <= `KC_CORE.pc;
        end
    end

    initial begin
        do_reset();
        wait (uart_rx_q.size() == BYTE_COUNT);
        repeat (20) @(posedge clk);
        for (int i = 0; i < BYTE_COUNT; i++) begin
            if (uart_rx_q[i] !== MESSAGE[i])
                $fatal(1, "FAIL: UART byte %0d was 0x%02h, expected 0x%02h", i, uart_rx_q[i], MESSAGE[i]);
            if (uart_rx_q[i] != 8'h0d) $write("%c", uart_rx_q[i]);
        end
        if (start_count < BYTE_COUNT) $fatal(1, "FAIL: %0d UART_TX writes, expected >= 15", start_count);
        if (!saw_loop_jump) $fatal(1, "FAIL: PC never jumped from 0x%08h to 0x00000004", LOOP_JAL);
        $display("PASS: program.mem transmitted 15 correct bytes");
        $finish;
    end

    initial begin
        #1_000_000;
        $fatal(1, "FAIL: timeout after 1 ms (received=%0d, pc=0x%08h)", uart_rx_q.size(), `KC_CORE.pc);
    end
endmodule
